+}
+#[cfg(test)]
+pub(in crate::cleanup_plan::replay) fn note_small_copy() {
+    SMALL_COPIES.with(|slot| slot.set(slot.get().checked_add(1).unwrap()));
+}
+#[cfg(test)]
+fn take_small_copies() -> usize {
+    SMALL_COPIES.with(|slot| slot.replace(0))
